CREATE OR REPLACE FUNCTION public._parse_epoch_ms(p_value text)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
  IF p_value IS NULL OR btrim(p_value) = '' THEN
    RETURN NULL;
  END IF;
  BEGIN
    RETURN p_value::bigint;
  EXCEPTION WHEN others THEN
    NULL;
  END;
  BEGIN
    RETURN round(p_value::numeric)::bigint;
  EXCEPTION WHEN others THEN
    NULL;
  END;
  BEGIN
    RETURN (extract(epoch FROM p_value::timestamptz) * 1000)::bigint;
  EXCEPTION WHEN others THEN
    NULL;
  END;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.research_funding_hfb1(p_oos_start_ms text DEFAULT NULL::text, p_as_of_event_time_ms text DEFAULT NULL::text, p_fee_bps numeric DEFAULT 4, p_slippage_bps numeric DEFAULT 1)
 RETURNS TABLE(horizon_minutes integer, n bigint, mean_gross_bps numeric, mean_net_bps numeric, win_rate numeric, net_ci95_low numeric, net_ci95_high numeric, first_event_time_ms bigint, last_event_time_ms bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '20s'
AS $function$
DECLARE
  v_oos_start_ms bigint := public._parse_epoch_ms(p_oos_start_ms);
  v_as_of_ms bigint := coalesce(
    public._parse_epoch_ms(p_as_of_event_time_ms),
    (SELECT max(funding_time_ms) FROM public.funding_rate_events WHERE symbol = 'BTCUSDT')
  );
  v_oos_start_effective bigint := coalesce(v_oos_start_ms, 0);
  v_fee_bps numeric := coalesce(p_fee_bps, 4);
  v_slippage_bps numeric := coalesce(p_slippage_bps, 1);
BEGIN
  IF v_as_of_ms IS NULL THEN
    RETURN QUERY SELECT 240::integer, 0::bigint, NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric, NULL::bigint, NULL::bigint;
    RETURN;
  END IF;

  RETURN QUERY
  WITH RECURSIVE params AS (
    SELECT 240::bigint*60*1000 AS horizon_ms, greatest(0, v_fee_bps)::numeric AS fee_bps, greatest(0, v_slippage_bps)::numeric AS slippage_bps
  ), base_events AS (
    SELECT e.symbol, e.funding_time_ms, e.funding_rate FROM public.funding_rate_events e
    WHERE e.symbol='BTCUSDT' AND e.funding_time_ms>=v_oos_start_effective AND e.funding_time_ms<=v_as_of_ms
  ), kept_events(symbol,funding_time_ms,funding_rate) AS (
    SELECT seed.symbol,seed.funding_time_ms,seed.funding_rate
    FROM (SELECT b.symbol,b.funding_time_ms,b.funding_rate FROM base_events b ORDER BY b.funding_time_ms LIMIT 1) seed
    UNION ALL
    SELECT next_e.symbol,next_e.funding_time_ms,next_e.funding_rate
    FROM kept_events k CROSS JOIN params p
    JOIN LATERAL (SELECT b.symbol,b.funding_time_ms,b.funding_rate FROM base_events b WHERE b.funding_time_ms>=k.funding_time_ms+p.horizon_ms ORDER BY b.funding_time_ms LIMIT 1) next_e ON true
  ), entries AS (
    SELECT e.*,CASE WHEN e.funding_rate>0 THEN 1 WHEN e.funding_rate<0 THEN -1 ELSE 0 END AS direction FROM kept_events e
  ), valid_entries AS (
    SELECT e.*,entry_bar.open AS entry_price,exit_bar.close AS exit_price FROM entries e
    JOIN LATERAL (SELECT o.open FROM public.ohlcv_1m o WHERE o.symbol=e.symbol AND o.interval='1m' AND o.open_time_ms>=e.funding_time_ms AND o.open>0 ORDER BY o.open_time_ms LIMIT 1) entry_bar ON true
    JOIN LATERAL (SELECT o.close FROM public.ohlcv_1m o,params p WHERE o.symbol=e.symbol AND o.interval='1m' AND o.open_time_ms>=e.funding_time_ms+p.horizon_ms AND o.close>0 ORDER BY o.open_time_ms LIMIT 1) exit_bar ON true
    WHERE e.direction<>0
  ), scored AS (
    SELECT v.*,v.direction*10000.0*(v.exit_price-v.entry_price)/v.entry_price AS price_gross_bps,
    -v.direction*10000.0*COALESCE((SELECT sum(f.funding_rate) FROM public.funding_rate_events f WHERE f.symbol=v.symbol AND f.funding_time_ms>v.funding_time_ms AND f.funding_time_ms<=v.funding_time_ms+p.horizon_ms),0) AS funding_cashflow_bps
    FROM valid_entries v,params p
  ), net AS (
    SELECT s.*,s.price_gross_bps+s.funding_cashflow_bps AS gross_bps,s.price_gross_bps+s.funding_cashflow_bps-2*(p.fee_bps+p.slippage_bps) AS net_bps FROM scored s,params p
  ), stats AS (
    SELECT count(*)::bigint AS n,avg(gross_bps) AS mean_gross_bps,avg(net_bps) AS mean_net_bps,avg((net_bps>0)::int)::numeric AS win_rate,sqrt(greatest(0,coalesce(variance(net_bps),0))/nullif(count(*),0)) AS se_net,min(funding_time_ms) AS first_event_time_ms,max(funding_time_ms) AS last_event_time_ms FROM net
  )
  SELECT 240::integer,s.n,s.mean_gross_bps,s.mean_net_bps,s.win_rate,s.mean_net_bps-1.96*coalesce(s.se_net,0),s.mean_net_bps+1.96*coalesce(s.se_net,0),s.first_event_time_ms,s.last_event_time_ms FROM stats s;
END;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
